[enu default]
Act_II = "Exhaustion";
Act_II_01 =
"\cDYou suddenly find yourself adrift between dreaming and being awake. It is difficult to make sense of this liminal state, as both wakefulness and unconsciousness struggle to stake a claim "
"over your personal reality.";
Act_II_02 =
"\cDAlas, it seems that exhaustion has won this time. It isn't just your eyelids that grow heavy, so does the muscles, the reflexes, even thoughts are becoming heavier...\n\n"
"And before you know it, weightlessness. Accompanied by a deep relaxation, free from any and all burden, physical and mental.";
Act_II_03 =
"\cDSoon, you will arrive. Invited to the crossroads. A world the naked eyes could not see -- only pure, naked minds.";
Bed_01a = "\cDIt looks inviting... maybe the 'dreams' will be better this time.";
Bed_01a_1 = "\cD[Sleep]";
Console = "Console";
Console_Fail = 
"\cDThe patterns and block structures of the encryption algorithm confuse you. You're at a complete loss on how to override this.\n\cR(WIT 2 Required)";
