Terminal_10b = "\cD[Check email]";
Terminal_10b_1 =
"\cJFrom: Ivan Ivanovich Ivanov\n"
"Subject: re:Forgot Password\n\n"
"\cUBrzeczyszczykiewicz, I've taken the liberty to reset and \write down your \cDnew password \cUonto a paper note. DO NOT LOSE THIS AGAIN. It should be in the big shop on this level, "
"check in the corner of the room if it's not on the front table. Also, if you see Kelly, could you ask her what she's drinking to cause her to laugh so loud?\n\n"
"Regards,\n"
"Ivan Ivanovich Ivanov.";
