Six_AltarA = "Ceremonial Flesh";
Six_AltarA01 = "\cDHallucinogenic cured flesh of a chosen ascendant. Eating this will shield your body from fragmenting when exposed to the Mind Palace.";
Six_AltarA01a = "\cD[Consume Ceremonial Flesh]";
Six_AltarA02 = "\cDYou eat the Ceremonial Flesh. There is a small chance your body will painfully dissolve into a pile of putrid sludge. You will remain completely aware, but won't be able to act on anything.";
Six_AltarB = "Ceremonial Blood";
Six_AltarB01 = "\cDPsychedelic venom infused with the brain of a chosen ascendant. Drinking this will shield your mind from collapsing when exposed to the Mind Palace.";
Six_AltarB01a = "\cD[Drink Ceremonial Blood]";
Six_AltarB02 = "\cDYou drink the Ceremonial Blood. There is a small chance your mind will plummet down the whirlpool of infinity, where you remain in complete darkness without thoughts or autonomy.";
